def rot(a): return tuple(tuple(row) for row in zip(*a[::-1]))
def flr(a): return tuple(tuple(r[::-1]) for r in a)
def variant(a,t):
 cur=a
 # t 0..7: rotate k then flip horizontally
 k=t//2; flip=t%2
 for _ in range(k):cur=rot(cur)
 return flr(cur) if flip else cur
def findid(base,a):
 return [t for t in range(8) if variant(base,t)==a]
